sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if ((isLoading && !g_form.isNewRecord()) || newValue === '' || newValue == oldValue) {
        return;
    }
    var getEmployeeDepartment = new GlideAjax('x_58872_needit.NeedIt_Due_Date_for_Sales');
    getEmployeeDepartment.addParam('sysparm_name', 'getDepartment');
    getEmployeeDepartment.addParam('sysparm_userID', newValue);
    getEmployeeDepartment.getXML(populateDepartmentField);
	console.log('hola');
console.log(newValue);
console.log('hola');

    function populateDepartmentField(response) {
        // Extraemos la respuesta del servidor
        var departmentFromScriptInclude = response.responseXML.documentElement.getAttribute("answer");
console.log(departmentFromScriptInclude);

        if (departmentFromScriptInclude == 'Sales') {
            g_form.clearValue('u_when_needed');

            var date = new Date();
            date.setDate(date.getDate() + 30);

            // Usamos las utilidades globales de ServiceNow para el formato
            var format = g_user_date_format;
            var dueDate = formatDate(date, format);

            g_form.setValue('u_when_needed', dueDate);
        }
    }
}
